function authAside(){return `<aside class="auth-aside"><div class="auth-aside-inner"><div class="auth-visual"><div class="auth-bars">${[28,42,37,61,55,78,70,91,84].map(h=>`<i style="--h:${h}%"></i>`).join('')}</div></div><div class="auth-quote">One login for your website, content, ads, and outreach.</div><div class="auth-caption">Everything your marketing needs, without the pile of subscriptions.</div></div></aside>`;}
function inputField(label,id,type='text',placeholder='',extra=''){return `<div class="field"><label for="${id}">${label}${extra}</label>${type==='password'?`<div class="password-wrap"><input class="input" id="${id}" name="${id}" type="password" placeholder="${placeholder}" required><button class="password-toggle" type="button" data-password="${id}" aria-label="Show password">◉</button></div>`:`<input class="input" id="${id}" name="${id}" type="${type}" placeholder="${placeholder}" required>`}</div>`;}
function authLayout(content){return `<div class="auth-wrap"><main class="auth-panel">${brand()}<div class="auth-card">${content}</div><div class="legal">By continuing, you agree to Nitro Outreach's Terms and acknowledge the Privacy Policy.</div></main>${authAside()}</div>`;}
function renderLogin(){document.title='Log in — Nitro Outreach';return authLayout(`<span class="eyebrow">Welcome back</span><h1>Log in to Nitro Outreach</h1><p>Continue building from your customer workspace.</p><form id="login-form">${inputField('Work email','email','email','you@company.com')}${inputField('Password','password','password','Your password','<a href="/forgot-password">Forgot password?</a>')}<label class="remember"><input type="checkbox" id="remember" checked> Keep me signed in for 30 days</label><button class="btn btn-primary btn-block btn-lg" type="submit">Log in</button><div class="form-status" id="form-status"></div></form><div class="auth-switch">New to Nitro Outreach? <a href="/signup">Create an account</a></div>`);}
function renderSignup(){document.title='Create your account — Nitro Outreach';return authLayout(`<span class="eyebrow">Start free</span><h1>Create your workspace</h1><p>Set up your account now. Choose a plan after email verification.</p><form id="signup-form"><div class="field-row">${inputField('First name','firstName','text','Ty')}${inputField('Last name','lastName','text','Smith')}</div>${inputField('Work email','email','email','you@company.com')}${inputField('Password','password','password','10+ characters')}<div class="form-note">Use at least 10 characters with uppercase, lowercase, and a number.</div><button class="btn btn-primary btn-block btn-lg" type="submit">Create account</button><div class="form-status" id="form-status"></div></form><div class="auth-switch">Already have an account? <a href="/login">Log in</a></div>`);}
function renderForgot(){document.title='Reset your password — Nitro Outreach';return authLayout(`<div class="mail-visual">↗</div><h1>Reset your password</h1><p>Enter your account email and we’ll send a secure reset link.</p><form id="forgot-form">${inputField('Work email','email','email','you@company.com')}<button class="btn btn-primary btn-block btn-lg" type="submit">Send reset link</button><div class="form-status" id="form-status"></div></form><div class="auth-switch"><a href="/login">← Back to login</a></div>`);}
function renderVerify(){document.title='Verify your email — Nitro Outreach';const token=qs('token'),failed=qs('delivery')==='failed';return authLayout(`<div class="mail-visual">${failed?'!':'✓'}</div><h1>${token?'Verifying your email':failed?'Let’s resend your email':'Check your inbox'}</h1><p>${token?'We’re securely confirming your account.':failed?'Your account was created, but the first verification message could not be delivered. Use the button below to send it again.':'Open the verification link we sent to finish creating your workspace.'}</p><div id="verify-state" class="form-status ${failed?'error':''}">${token?'Please wait…':failed?'Verification email delivery failed. Your account is safe—resend it now.':'The link expires in 24 hours.'}</div>${token?'':'<form id="resend-form">'+inputField('Email','email','email','you@company.com')+'<button class="btn btn-primary btn-block" type="submit">Resend verification</button></form>'}<div class="auth-switch"><a href="/login">Return to login</a></div>`);}
function renderReset(){document.title='Choose a new password — Nitro Outreach';return authLayout(`<div class="mail-visual">⌁</div><h1>Choose a new password</h1><p>Create a strong password you haven’t used for this account before.</p><form id="reset-form">${inputField('New password','password','password','10+ characters')}${inputField('Confirm password','confirmPassword','password','Repeat password')}<button class="btn btn-primary btn-block btn-lg" type="submit">Update password</button><div class="form-status" id="form-status"></div></form>`);}

function pricingBlock(compact=false){return `<div class="billing-toggle"><button data-interval="monthly" class="${state.interval==='monthly'?'active':''}">Monthly</button><button data-interval="yearly" class="${state.interval==='yearly'?'active':''}">Yearly <span class="save-badge">SAVE ~17%</span></button></div><div class="pricing-grid">${Object.values(PLANS).map(p=>priceCard(p,compact)).join('')}</div>`;}
function priceCard(p){const yr=state.interval==='yearly';const amount=p.id==='free'?0:(yr?Math.round(p.yearly/12):p.monthly);const unit=p.id==='free'?'':'/mo';const monthly=p.id==='free'?'Free forever':(yr?`billed yearly · ${money(p.yearly)}/yr`:'billed monthly');return `<article class="price-card ${p.recommended?'recommended':''}">${p.recommended?'<span class="recommend-badge">RECOMMENDED</span>':''}<div class="price-name">${p.name}</div><div class="price-desc">${p.desc}</div><div class="price">${money(amount)}<small>${p.id==='free'?'':unit}</small></div><div class="price-note">${monthly}</div><a class="btn ${p.recommended?'btn-primary':''}" href="${checkoutLink(p.id)}">${p.id==='free'?'Start free':state.session?'Choose '+p.name:'Get started'}</a><ul class="feature-list">${p.features.map(f=>`<li>${f}</li>`).join('')}</ul></article>`;}
function checkoutLink(planId){if(!state.session)return `/signup?plan=${planId}&interval=${state.interval}`;if(planId==='free')return state.session.user?.onboarding?.completed?'/app':'/welcome';return `/checkout?plan=${planId}&interval=${state.interval}`;}
function renderPricing(){document.title='Pricing — Nitro Outreach';return `<div class="pricing-page">${publicNav()}<section class="pricing-section"><div class="section-head"><span class="eyebrow">Clear, flexible pricing</span><h2>A plan for every stage of growth.</h2><p>Start with the essentials, then unlock the complete operating system as your business grows.</p></div>${pricingBlock()}</section>${footer()}</div>`;}

function selectedCheckout(){const id=qs('plan')||sessionStorage.getItem('nitro-plan')||'growth';const interval=qs('interval')||sessionStorage.getItem('nitro-interval')||state.interval;const chosen=plan(id);sessionStorage.setItem('nitro-plan',chosen.id);sessionStorage.setItem('nitro-interval',interval);return {chosen,interval,amount:interval==='yearly'?chosen.yearly:chosen.monthly};}
function checkoutSteps(active){return `<div class="checkout-steps">${['Review','Payment','Complete'].map((x,i)=>`${i?'<span class="checkout-line"></span>':''}<span class="checkout-step ${i<active?'done':i===active?'active':''}"><i>${i<active?'✓':i+1}</i>${x}</span>`).join('')}</div>`;}
function orderSummary(data,button=''){return `<aside class="checkout-card order-summary"><span class="plan-pill">${data.chosen.name} plan</span><div class="summary-price">${money(data.amount)}<small>/${data.interval==='yearly'?'year':'month'}</small></div><p>${data.chosen.desc}</p><ul class="feature-list">${data.chosen.features.slice(0,6).map(x=>`<li>${x}</li>`).join('')}</ul><div class="summary-total"><span>Due today</span><strong>${state.session?.stripeConfigured?money(data.amount):'$0'}</strong></div>${button}</aside>`;}
function renderCheckout(){document.title='Review your plan — Nitro Outreach';const data=selectedCheckout();return `<div class="checkout-wrap">${publicNav()}<main class="checkout-main">${checkoutSteps(0)}<div class="checkout-grid"><section class="checkout-card"><span class="eyebrow">Plan review</span><h1>Confirm your selection</h1><p>Review your plan and billing cadence before continuing to secure payment.</p><div class="review-list"><div class="review-row"><span>Plan</span><strong>${data.chosen.name}</strong></div><div class="review-row"><span>Billing</span><strong>${data.interval==='yearly'?'Annual':'Monthly'}</strong></div><div class="review-row"><span>Renewal</span><strong>Automatic until canceled</strong></div><div class="review-row"><span>Trial</span><strong>14 days</strong></div></div><div style="display:flex;gap:9px;margin-top:25px"><a class="btn" href="/pricing">Change plan</a><a class="btn btn-primary" href="/checkout/payment?plan=${data.chosen.id}&interval=${data.interval}">Continue to payment →</a></div></section>${orderSummary(data)}</div></main></div>`;}
function renderPayment(){document.title='Payment — Nitro Outreach';const data=selectedCheckout();const demo=!state.session?.stripeConfigured;return `<div class="checkout-wrap">${publicNav()}<main class="checkout-main">${checkoutSteps(1)}<div class="checkout-grid"><section class="checkout-card"><span class="eyebrow">Secure checkout</span><h1>${demo?'Preview payment flow':'Payment details'}</h1><p>${demo?'Stripe is not connected yet. This screen demonstrates the complete handoff and starts a no-charge demo trial.':'Enter your payment details securely through Stripe.'}</p>${demo?'<div class="demo-banner"><b>DEMO CHECKOUT</b><br>No card will be charged. A trialing subscription record will be created so you can test the customer experience.</div>':''}<div class="field"><label>Name on card</label><input class="input" placeholder="Ty Smith" ${demo?'disabled':''}></div><div class="field"><label>Card information</label><div class="card-mock"><div class="card-fields"><input class="input" placeholder="1234 1234 1234 1234" disabled><input class="input" placeholder="MM / YY" disabled><input class="input" placeholder="CVC" disabled></div></div></div><div class="field"><label>Billing country</label><select class="select" ${demo?'disabled':''}><option>United States</option></select></div><button id="activate-plan" class="btn btn-primary btn-block btn-lg">${demo?'Start demo trial':'Subscribe securely'}</button><div class="form-status" id="form-status"></div></section>${orderSummary(data)}</div></main></div>`;}
function renderSuccess(){document.title='Subscription active — Nitro Outreach';const p=plan(state.session?.user?.subscription?.plan);return `<div class="checkout-wrap">${publicNav()}<main class="checkout-main">${checkoutSteps(2)}<section class="checkout-card success-card"><div class="success-icon">✓</div><span class="eyebrow">Setup complete</span><h1>Your ${p.name} workspace is ready.</h1><p>${state.session?.user?.subscription?.billingMode==='demo'?'Your no-charge demo subscription is active. Connect Stripe before accepting real customer payments.':'Your subscription is active and your workspace limits have been updated.'}</p><a class="btn btn-primary btn-lg" href="${state.session?.user?.onboarding?.completed?'/app':'/welcome'}">Continue to workspace →</a></section></main></div>`;}

const ONBOARD_STEPS=[
  ['Company name','What should we call your workspace?'],['Industry','Help Nitro Outreach tailor recommendations.'],['Website','Connect your current online home.'],['Brand colors','Set the visual foundation for generated work.'],['Logo','Give your workspace a recognizable identity.'],['Goals','Choose what you want to accomplish first.'],['Social accounts','Prepare your channels for future connections.'],['Ready to build','Review the foundation of your workspace.']
];
function renderWelcome(){document.title='Set up your workspace — Nitro Outreach';const stored=state.session?.user?.onboarding||{};if(!state.onboardInitialized){state.onboardStep=Math.max(1,Math.min(8,stored.step||1));state.onboardData={goals:[],socials:[],...(stored.data||{})};state.onboardInitialized=true;}const meta=ONBOARD_STEPS[state.onboardStep-1];return `<div class="onboarding-shell"><aside class="onboarding-side">${brand()}<h2>Build your foundation.</h2><p>Nitro Outreach uses this information to personalize your workspace, content, and recommendations.</p><div class="progress-track"><i style="--progress:${state.onboardStep/8*100}%"></i></div><div class="step-label">Step ${state.onboardStep} of 8 · ${meta[0]}</div></aside><main class="onboarding-main"><section class="onboarding-card"><span class="step-kicker">Step ${state.onboardStep} of 8</span><h1>${meta[0]}</h1><p>${meta[1]}</p>${onboardStepContent()}<div class="onboard-actions">${state.onboardStep>1?'<button class="btn" id="onboard-back">← Back</button>':'<span></span>'}<button class="btn btn-primary btn-lg" id="onboard-next">${state.onboardStep===8?'Finish setup':'Continue →'}</button></div><button class="onboard-skip" id="onboard-skip" type="button">Skip for now — I'll finish this later</button><div class="form-status" id="form-status"></div></section></main></div>`;}
function onboardStepContent(){const d=state.onboardData;switch(state.onboardStep){
  case 1:return `<div class="field"><label>Company or brand name</label><input id="onboard-value" class="input" value="${esc(d.companyName||'')}" placeholder="Acme Inc" autofocus></div>`;
  case 2:return `<div class="field"><label>Industry</label><select id="onboard-value" class="select"><option value="">Select an industry</option>${['Agency','Professional services','Home services','Health & wellness','Real estate','E-commerce','Software','Education','Other'].map(x=>`<option ${d.industry===x?'selected':''}>${x}</option>`).join('')}</select></div>`;
  case 3:return `<div class="field"><label>Website URL <span>Optional</span></label><input id="onboard-value" class="input" value="${esc(d.websiteUrl||'')}" placeholder="yourcompany.com"></div><div class="notice">No website yet? Skip this step and create one from your workspace later.</div>`;
  case 4:return `<div class="color-grid"><div class="color-field"><label>Primary color</label><input id="primaryColor" type="color" value="${esc(d.primaryColor||'#ff6b00')}"></div><div class="color-field"><label>Secondary color</label><input id="secondaryColor" type="color" value="${esc(d.secondaryColor||'#ffb000')}"></div></div>`;
  case 5:return `<label class="logo-uploader" for="logo-upload">${d.logoData?`<img class="logo-uploader-img" src="${d.logoData}" alt="Logo"><span class="logo-uploader-title">Logo ready</span><span class="logo-uploader-sub">Click to replace it</span>`:`<span class="logo-uploader-icon">↥</span><span class="logo-uploader-title">Upload your logo</span><span class="logo-uploader-sub">PNG, JPG, or WebP · under 350 KB</span>`}<input id="logo-upload" type="file" accept="image/png,image/jpeg,image/webp" hidden></label>`;
  case 6:return `<div class="choice-grid">${['Get more customers','Launch a better website','Create consistent content','Run profitable ads','Save time with AI','Understand performance'].map(x=>`<button class="choice ${(d.goals||[]).includes(x)?'active':''}" data-goal="${esc(x)}">${x}</button>`).join('')}</div>`;
  case 7:return `<div class="social-row">${['Instagram','Facebook','LinkedIn','TikTok','YouTube','X'].map(x=>`<button class="social-chip ${(d.socials||[]).includes(x)?'active':''}" data-social="${x}">${x}</button>`).join('')}</div><div class="notice" style="margin-top:18px">Connections are placeholders for now. You can finish secure OAuth setup from Social Media later.</div>`;
  default:return `<div class="glass-card panel"><div class="review-row"><span>Workspace</span><strong>${esc(d.companyName||'Your company')}</strong></div><div class="review-row"><span>Industry</span><strong>${esc(d.industry||'Not selected')}</strong></div><div class="review-row"><span>Website</span><strong>${esc(d.websiteUrl||'Create later')}</strong></div><div class="review-row"><span>Goals selected</span><strong>${(d.goals||[]).length}</strong></div></div>`;
}}

function sectionFromHash(){const key=location.hash.replace('#','');return (NAV.some(x=>x[0]===key)||(key==='owner'&&(state.session?.user?.email||'').toLowerCase()===OWNER_EMAIL))?key:'dashboard';}
function appShell(){const section=sectionFromHash(),user=state.session.user,workspace=user.companyName||user.onboarding?.data?.companyName||'My workspace';const bd=user.onboarding?.data||{},primary=bd.primaryColor||'#ff6b00',secondary=bd.secondaryColor||'#ffb000',brandLogo=bd.logoData;return `<style>#customer-shell .btn-primary{background:linear-gradient(120deg,${primary},${secondary})!important;color:#fff!important;border-color:transparent!important;box-shadow:0 10px 26px ${primary}3d!important}#customer-shell .btn-primary:hover{filter:brightness(1.1)}#customer-shell .workspace-logo,#customer-shell .avatar{background:linear-gradient(135deg,${primary},${secondary})!important;color:#fff!important}#customer-shell .workspace-logo svg,#customer-shell .avatar svg{width:18px;height:18px}#customer-shell .side-link.active{box-shadow:inset 3px 0 0 ${primary}!important;background:linear-gradient(90deg,${primary}1f,${primary}05)!important}#customer-shell .stat-icon,#customer-shell .feature-icon{background:${primary}1f!important;border-color:${primary}40!important;color:${primary}!important}#customer-shell .activity-dot{background:${primary}1f!important;color:${primary}!important}#customer-shell .chart-bar i{background:linear-gradient(180deg,${primary},${primary}22)!important}#customer-shell .chart-bar i.alt{background:linear-gradient(180deg,${secondary},${secondary}22)!important}#customer-shell .plan-pill,#customer-shell .price-pill{color:${primary}!important;border-color:${primary}47!important;background:${primary}14!important}#customer-shell .recommend-badge{background:linear-gradient(135deg,${primary},${secondary})!important;color:#fff!important}#customer-shell .chat-av-user{background:linear-gradient(135deg,${primary},${secondary})!important;color:#fff!important}#customer-shell .chat-av-bot,#customer-shell .msg-chan.is-email{background:${primary}1f!important;color:${primary}!important}#customer-shell .chat-row.user .chat-bubble{background:linear-gradient(120deg,${primary},${secondary})!important;color:#fff!important}#customer-shell .chat-item.active{border-color:${primary}55!important}#customer-shell .msg-tab.active{border-color:${primary}!important;color:#fff!important;background:${primary}22!important}#customer-shell .auto-step span,#customer-shell .auto-tag{background:${primary}1f!important;color:${primary}!important}#customer-shell .empty-icon{color:${primary}!important}</style><div class="customer-shell ${state.mobileMenu?'menu-open':''}" id="customer-shell" style="--green:${primary};--green2:${primary};--aqua:${secondary};--purple:${primary};--line2:${primary}52"><aside class="sidebar">${brand()}<div class="workspace-switch">${brandLogo?`<span class="workspace-logo has-img"><img src="${brandLogo}" alt=""></span>`:`<span class="workspace-logo">${nitroMark()}</span>`}<span><b>${esc(workspace)}</b><small>${esc(plan(user.subscription?.plan).name)} workspace</small></span></div><div class="side-label">Workspace</div><nav class="side-nav">${NAV.slice(0,8).map(x=>sideLink(x,section)).join('')}</nav><div class="sidebar-bottom"><div class="side-label">Account</div><nav class="side-nav">${NAV.slice(8).map(x=>sideLink(x,section)).join('')}</nav>${(user.email||'').toLowerCase()===OWNER_EMAIL?`<div class="side-label">Owner</div><nav class="side-nav">${sideLink(['owner','◆','Owner'],section)}</nav>`:''}<div class="user-mini"><span class="avatar">${nitroMark()}</span><span><b>${esc(user.firstName+' '+user.lastName)}</b><small>${esc(user.email)}</small></span><button class="logout-icon" id="logout-btn" title="Log out">↗</button></div></div></aside><div class="menu-backdrop" id="menu-backdrop"></div><main class="main-area"><header class="app-topbar"><div style="display:flex;align-items:center;gap:11px"><button class="icon-btn mobile-menu" id="mobile-menu">☰</button><div class="page-title"><h1>${section==='owner'?'Owner':(NAV.find(x=>x[0]===section)?.[2]||'Dashboard')}</h1><p>${sectionSubtitle(section)}</p></div></div><div class="top-actions"><a class="btn btn-primary" href="#assistant">✦ Ask Nitro</a></div></header><div class="app-content">${renderAppSection(section)}</div></main></div>`;}
function sideLink(item,current){return `<a class="side-link ${item[0]===current?'active':''}" href="#${item[0]}"><span class="side-icon">${ICONS[item[0]]||item[1]}</span>${item[2]}</a>`;}
function sectionSubtitle(s){return ({dashboard:'Your business at a glance',websites:'Build and manage your online presence',content:'Create campaign-ready content',social:'Plan and publish across channels',ads:'Launch and optimize paid campaigns',messages:'Manage sent email & SMS and set up automation',assistant:'Work with your context-aware AI',analytics:'See what is moving the business',billing:'Manage plans and payments',settings:'Control your account and workspace'}[s]||'');}
function renderAppSection(section){switch(section){case'owner':return ownerPage();case'websites':return modulePage('Websites','Create Website','◇','Your website library is ready','Create and manage conversion-focused websites for your business.','New website');case'content':return contentStudioPage();case'social':return modulePage('Social Media','Connect Account','◎','Connect your first social channel','Schedule posts and manage publishing once your social accounts are connected.','Connect account');case'ads':return modulePage('Ad Campaigns','Launch Campaign','◈','Launch your first campaign','Build campaign briefs, organize creative, and track performance from one place.','Create campaign');case'messages':return messagesPage();case'assistant':return assistantPage();case'analytics':return analyticsPage();case'billing':return billingPage();case'settings':return settingsPage();default:return dashboardHome();}}
function contentStudioPage(){
  const w=workspaceData(),items=w.content||[],user=state.session.user,isOwner=(user.email||'').toLowerCase()===OWNER_EMAIL,credits=Number(user.usage?.videoCredits||0);
  const creditLabel=isOwner?'Unlimited · Owner':`${credits} Reel Credit${credits===1?'':'s'}`;
  const contentRows=items.map(i=>{
    if(i.type==='video')return `<div class="activity-item content-video-item"><video class="gen-video" src="${esc(i.mediaUrl)}" preload="metadata"></video><span class="content-video-copy"><b>${esc(i.topic)}</b><p class="content-sub">${i.duration?esc(i.duration)+' sec · ':''}AI motion Reel · Ready to export</p>${i.prompt?`<small>${esc(i.prompt)}</small>`:''}</span><div class="reel-item-actions"><button class="btn btn-sm btn-watch-reel" data-preview-reel="${esc(i.id)}" data-reel-url="${esc(i.mediaUrl)}" data-reel-title="${esc(i.topic)}">▶ Watch Reel</button><a class="btn btn-sm" href="${esc(i.mediaUrl)}" download="nitro-ai-reel.mp4">Download</a><button class="btn btn-sm ig-post-btn" data-ig-reel="${esc(i.id)}">Post Reel to IG</button><button class="btn btn-sm btn-delete-reel" data-del-item="content" data-del-id="${esc(i.id)}">Delete</button></div></div>`;
    if(i.type==='carousel')return `<div class="activity-item carousel-item"><div class="carousel-info"><b>${esc(i.topic)}</b><p class="content-sub">${(i.slides||[]).length}-slide carousel${i.postedToInstagram?' · ✓ posted':''}</p><div class="carousel-strip">${(i.slides||[]).map((s,idx)=>`<a class="carousel-slide" href="/api/customer-image?id=${esc(s.id)}" download="slide-${idx+1}.png"><img src="/api/customer-image?id=${esc(s.id)}" loading="lazy" alt="Slide ${idx+1}"><span class="carousel-num">${idx+1}</span></a>`).join('')}</div><button class="btn btn-sm ig-post-btn" data-ig-post="${esc(i.id)}">Post carousel to IG</button></div><button class="card-del" data-del-item="content" data-del-id="${esc(i.id)}" title="Delete">×</button></div>`;
    if(i.type==='image')return `<div class="activity-item content-image-item"><img class="gen-img" src="/api/customer-image?id=${esc(i.id)}" alt="${esc(i.topic)}" loading="lazy"><span><b>${esc(i.topic)}</b><p class="content-sub">AI image${i.size?' · '+esc(i.size):''}</p></span><button class="btn btn-sm ig-post-btn" data-ig-post="${esc(i.id)}">Post to IG</button><a class="btn btn-sm" href="/api/customer-image?id=${esc(i.id)}" download="nitro-image.png">Download</a><button class="card-del" data-del-item="content" data-del-id="${esc(i.id)}" title="Delete">×</button></div>`;
    return `<div class="activity-item"><span class="activity-dot">✦</span><span><b>${esc(i.topic)}</b><p>${esc(i.text)}</p></span><time>${new Date(i.createdAt).toLocaleDateString()}</time><button class="card-del" data-del-item="content" data-del-id="${esc(i.id)}" title="Delete">×</button></div>`;
  }).join('');
  return `<div class="section-toolbar"><div><h2>Content Studio</h2><p>Describe the ad. Nitro turns it into one continuous cinematic Reel.</p></div><div class="content-actions"><span class="video-credit-pill ${isOwner?'owner-unlimited':''}">${creditLabel}</span>${isOwner?'':'<button class="btn" data-buy-video-credits>Buy credits</button>'}<button class="btn btn-reel" data-workspace-action="video">✦ Create AI Reel</button><button class="btn" data-workspace-action="content-carousel">◇ Carousel</button><button class="btn" data-workspace-action="content-image">✦ Image</button><button class="btn btn-primary" data-workspace-action="content">+ Content</button></div></div><section class="reel-callout prompt-reel-callout glass-card"><div class="reel-orb">✦</div><div><span class="eyebrow">PROMPT → FINISHED AD</span><h3>Tell Nitro what you want to advertise.</h3><p>No script needed. Nitro creates moving cinematic visuals that flow together, a natural voiceover, music, caption, and CTA—without slide sections.</p><div class="reel-price-row"><span>15 sec · 1 credit</span><span>30 sec · 2 credits</span><span>45 sec · 3 credits</span>${isOwner?'':'<a href="#billing">Open credit store →</a>'}</div></div><button class="btn btn-primary" data-workspace-action="video">Create an ad</button></section>${items.length?`<div class="activity-list glass-card panel">${contentRows}</div>`:`<section class="glass-card"><div class="empty-state"><div class="empty-icon">✦</div><h3>Create your first prompt-powered Reel</h3><p>Choose a proven idea, customize it in your own words, and Nitro turns it into a flowing vertical video ad.</p><button class="btn btn-reel" data-workspace-action="video">Create AI Reel</button></div></section>`}`;
}
function dashboardHome(){const u=state.session.user,p=plan(u.subscription?.plan),used=u.usage?.aiUsed||0,remaining=p.credits===null?'Unlimited':Math.max(0,p.credits-used),websites=u.usage?.websites||0;return `<div class="welcome-row"><div><h2>Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${esc(u.firstName||'there')}.</h2><p>Your AI growth engine is running.</p></div><a class="btn" href="#settings">Customize workspace</a></div><div class="stat-grid">${stat('Current plan',p.name,u.subscription?.status==='trialing'?'14-day demo trial':'Active','▣')}${stat('AI credits',remaining,p.credits===null?'No generation cap':used+' used this cycle','✦')}${stat('Websites',websites,websites?'Active projects':'Ready to create','◇')}${stat('Campaign performance','—','Connect data to begin','⌁')}</div><div class="dashboard-grid"><section class="glass-card panel"><div class="panel-head"><h3>Performance overview</h3><span>Last 30 days ▾</span></div><div class="chart-wrap"><div class="chart-grid"></div>${[25,33,29,42,38,48,45,55,50,62,58,72].map((h,i)=>`<div class="chart-bar"><i style="--h:${h}%"></i><i class="alt" style="--h:${Math.max(8,h-12+(i%3)*4)}%"></i></div>`).join('')}</div><div class="chart-labels"><span>Week 1</span><span>Week 2</span><span>Week 3</span><span>Week 4</span></div><div class="notice" style="margin-top:17px">Connect websites, social accounts, or ad platforms to replace this preview with live performance data.</div></section><section class="glass-card panel"><div class="panel-head"><h3>Quick actions</h3><span>Start something</span></div><div class="quick-grid">${[['◇','Create Website','websites'],['✦','Generate Content','content'],['◎','Schedule Posts','social'],['◈','Launch Ads','ads']].map(x=>`<a class="quick-action" href="#${x[2]}"><span class="feature-icon">${x[0]}</span><b>${x[1]}</b><small>Open workspace →</small></a>`).join('')}</div></section></div><div class="dashboard-grid"><section class="glass-card panel"><div class="panel-head"><h3>Recent activity</h3><span>View all</span></div><div class="activity-list"><div class="activity-item"><span class="activity-dot">✓</span><span><b>Workspace created</b><p>Your Nitro Outreach customer workspace is ready.</p></span><time>Today</time></div>${u.onboarding?.completed?'<div class="activity-item"><span class="activity-dot">✦</span><span><b>Onboarding completed</b><p>Your company profile now powers future recommendations.</p></span><time>Today</time></div>':''}</div></section><section class="glass-card panel"><div class="panel-head"><h3>Recent AI generations</h3><a href="#content">Open studio</a></div><div class="empty-state" style="padding:26px"><div class="empty-icon">✦</div><h3>No generations yet</h3><p>Your latest content and AI work will appear here.</p></div></section></div>`;}
function stat(label,value,sub,icon){return `<article class="glass-card stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${esc(value)}</div><div class="stat-sub">${esc(sub)}</div></article>`;}
function workspaceData(){return state.session?.user?.workspace||{websites:[],content:[],socialDrafts:[],campaigns:[],assistant:[],messages:[],connections:{email:{connected:false},sms:{connected:false}}};}
function upgradeCard(title,copy){return `<section class="glass-card" style="margin-top:12px"><div class="empty-state"><div class="empty-icon">↗</div><h3>${title}</h3><p>${copy}</p><a class="btn btn-primary" href="/pricing">View plans</a></div></section>`;}
function modulePage(title,action,icon,emptyTitle,emptyText,button){const kind=sectionFromHash(),w=workspaceData(),p=plan(state.session.user.subscription?.plan);if(kind==='websites'){const sites=w.websites||[];return `<div class="section-toolbar"><div><h2>Websites</h2><p>Build and manage your online presence.</p></div><button class="btn btn-primary" data-workspace-action="website">+ Create Website</button></div>${sites.length?`<div class="module-grid">${sites.map(s=>`<article class="glass-card module-card"><button class="card-del" data-del-item="website" data-del-id="${esc(s.id)}" title="Delete">×</button><span class="feature-icon">◇</span><h3>${esc(s.name)}</h3><p>${esc(s.industry||'')}</p><span class="plan-pill">${esc(s.status)}</span>${s.url?`<div style="margin-top:12px;display:flex;gap:8px;flex-wrap:wrap"><a class="btn btn-primary" href="${esc(s.url)}" target="_blank" rel="noopener">Preview →</a><button class="btn" data-download-site="${esc(s.id)}">Download</button><button class="btn" data-copy-link="${esc(s.url)}">Copy link</button></div>`:''}</article>`).join('')}</div>`:`<section class="glass-card"><div class="empty-state"><div class="empty-icon">◇</div><h3>Build your first website</h3><p>Answer two quick questions and Nitro builds you a complete, ready-to-share site in about a minute.</p><button class="btn btn-primary" data-workspace-action="website">Create Website</button></div></section>`}${p.id==='free'?'<div class="notice" style="margin-top:12px">Free includes one website project.</div>':''}`;}if(kind==='content'){const items=w.content||[],videoCredits=Number(state.session.user.usage?.videoCredits||0);return `<div class="section-toolbar"><div><h2>Content Studio</h2><p>Turn ideas and raw screen recordings into campaign-ready content.</p></div><div class="content-actions"><span class="video-credit-pill">${videoCredits} Video Credit${videoCredits===1?'':'s'}</span><button class="btn" data-buy-video-credits>Buy credits</button><button class="btn btn-reel" data-workspace-action="video">▶ Create Reel</button><button class="btn" data-workspace-action="content-carousel">◇ Carousel</button><button class="btn" data-workspace-action="content-image">✦ Image</button><button class="btn btn-primary" data-workspace-action="content">+ Content</button></div></div><section class="reel-callout glass-card"><div class="reel-orb">▶</div><div><span class="eyebrow">NITRO REEL EDITOR</span><h3>Upload a raw screen recording. Get a polished vertical ad.</h3><p>Automatic 9:16 layout, cinematic motion, branded titles, CTA, audio leveling, and an Instagram-ready MP4.</p></div><button class="btn btn-primary" data-workspace-action="video">Upload video</button></section>${items.length?`<div class="activity-list glass-card panel">${items.map(i=>i.type==='video'?`<div class="activity-item content-video-item"><video class="gen-video" src="${esc(i.mediaUrl)}" preload="metadata"></video><span><b>${esc(i.topic)}</b><p class="content-sub">Instagram Reel · Ready to export</p></span><a class="btn btn-sm" href="${esc(i.mediaUrl)}" download="nitro-reel.mp4">Download</a><button class="btn btn-sm ig-post-btn" data-ig-reel="${esc(i.id)}">Post Reel to IG</button><button class="card-del" data-del-item="content" data-del-id="${esc(i.id)}" title="Delete">×</button></div>`:i.type==='carousel'?`<div class="activity-item carousel-item"><div class="carousel-info"><b>${esc(i.topic)}</b><p class="content-sub">${(i.slides||[]).length}-slide carousel${i.postedToInstagram?' · ✓ posted':''}</p><div class="carousel-strip">${(i.slides||[]).map((s,idx)=>`<a class="carousel-slide" href="/api/customer-image?id=${esc(s.id)}" download="slide-${idx+1}.png" title="${esc(s.caption||('Slide '+(idx+1)))}"><img src="/api/customer-image?id=${esc(s.id)}" loading="lazy" alt="Slide ${idx+1}"><span class="carousel-num">${idx+1}</span></a>`).join('')}</div><button class="btn btn-sm ig-post-btn" data-ig-post="${esc(i.id)}" style="margin-top:10px">Post carousel to IG</button></div><button class="card-del" data-del-item="content" data-del-id="${esc(i.id)}" title="Delete">×</button></div>`:i.type==='image'?`<div class="activity-item content-image-item"><img class="gen-img" src="/api/customer-image?id=${esc(i.id)}" alt="${esc(i.topic)}" loading="lazy"><span><b>${esc(i.topic)}</b><p class="content-sub">AI image${i.size?' · '+esc(i.size):''}${i.postedToInstagram?' · ✓ posted':''}</p></span><button class="btn btn-sm ig-post-btn" data-ig-post="${esc(i.id)}">Post to IG</button><a class="btn btn-sm" href="/api/customer-image?id=${esc(i.id)}" download="nitro-image.png">Download</a><button class="card-del" data-del-item="content" data-del-id="${esc(i.id)}" title="Delete">×</button></div>`:`<div class="activity-item"><span class="activity-dot">✦</span><span><b>${esc(i.topic)}</b><p>${esc(i.text)}</p></span><time>${new Date(i.createdAt).toLocaleDateString()}</time><button class="card-del" data-del-item="content" data-del-id="${esc(i.id)}" title="Delete">×</button></div>`).join('')}</div>`:`<section class="glass-card"><div class="empty-state"><div class="empty-icon">✦</div><h3>Turn an idea into content</h3><p>Write ready-to-post copy, generate a marketing image, or create your first Reel.</p><div style="display:flex;gap:8px;justify-content:center;flex-wrap:wrap"><button class="btn btn-reel" data-workspace-action="video">Create Reel</button><button class="btn" data-workspace-action="content-image">Generate Image</button><button class="btn btn-primary" data-workspace-action="content">Generate Content</button></div></div></section>`}`;}if(kind==='social'){if(p.id==='free')return `<div class="section-toolbar"><div><h2>Social Media</h2><p>Plan publishing across connected channels.</p></div></div>${upgradeCard('Social scheduling is available on Starter','Upgrade to create drafts, connect supported channels, and schedule publishing.')}`;const drafts=w.socialDrafts||[];return `<div class="section-toolbar"><div><h2>Social Media</h2><p>Schedule posts to go out on a set date and time.</p></div><button class="btn btn-primary" data-workspace-action="social">+ Schedule Post</button></div>${(()=>{const m=state.session.user.meta;return m&&m.igUsername?`<div class="notice" style="margin-bottom:12px">✓ Connected to Instagram as <b>@${esc(m.igUsername)}</b> — scheduled posts with an image auto-publish.</div>`:`<div class="glass-card" style="padding:16px;margin-bottom:12px;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap"><span style="font-size:13px;color:#9aa09c">Connect your Instagram to auto-publish scheduled posts.</span><a class="btn btn-primary" href="/api/meta-connect">Connect Instagram</a></div>`;})()}${drafts.length?`<div class="activity-list glass-card panel">${drafts.map(d=>`<div class="activity-item"><span class="activity-dot">◎</span><span><b>${d.status==='scheduled'?'Scheduled':d.status==='published'?'Published':'Draft'} · ${esc(d.platform||'instagram')}</b><p>${esc(d.text)}</p></span><time>${d.scheduledFor?new Date(d.scheduledFor).toLocaleString():new Date(d.createdAt).toLocaleDateString()}</time><button class="card-del" data-del-item="social" data-del-id="${esc(d.id)}" title="Delete">×</button></div>`).join('')}</div>`:`<section class="glass-card"><div class="empty-state"><div class="empty-icon">◎</div><h3>Schedule your first post</h3><p>Write your copy and pick a date and time — Nitro keeps it queued and ready to publish.</p><button class="btn btn-primary" data-workspace-action="social">Schedule Post</button></div></section>`}`;}if(kind==='ads'){if(!['growth','pro','scale'].includes(p.id))return `<div class="section-toolbar"><div><h2>Ad Campaigns</h2><p>Build campaign briefs and track performance.</p></div></div>${upgradeCard('Ad campaign management starts on Growth','Upgrade to create campaign briefs and organize paid-media work.')}`;const campaigns=w.campaigns||[];return `<div class="section-toolbar"><div><h2>Ad Campaigns</h2><p>Generate a complete, ready-to-launch ad plan.</p></div><button class="btn btn-primary" data-workspace-action="campaign">+ Build Campaign</button></div>${campaigns.length?`<div class="module-grid">${campaigns.map(c=>`<article class="glass-card module-card" style="grid-column:1/-1"><button class="card-del" data-del-item="campaign" data-del-id="${esc(c.id)}" title="Delete">×</button><span class="feature-icon">◈</span><h3>${esc(c.name)}</h3><p>${esc(c.objective||'')}${c.budget?' · '+esc(c.budget):''}</p><span class="plan-pill">${esc(c.status)}</span>${c.plan?`<details style="margin-top:12px"><summary style="cursor:pointer;color:var(--green);font-weight:600">View campaign plan</summary><div style="white-space:pre-wrap;margin-top:10px;font-size:13px;line-height:1.65;color:#c9cdca">${esc(c.plan)}</div></details>`:''}</article>`).join('')}</div>`:`<section class="glass-card"><div class="empty-state"><div class="empty-icon">◈</div><h3>Build your first campaign</h3><p>Tell Nitro your objective and budget — it writes the audience, ad copy, creative direction, and a launch checklist you can follow.</p><button class="btn btn-primary" data-workspace-action="campaign">Build Campaign</button></div></section>`}`;}return '';}
function mdToHtml(src){
  function inline(t){t=esc(t);t=t.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');t=t.replace(/`([^`]+)`/g,'<code>$1</code>');t=t.replace(/\[[ xX]?\]\s*/g,'');return t;}
  var lines=String(src||'').split(/\r?\n/),out=[],inList=false;
  function closeList(){if(inList){out.push('</ul>');inList=false;}}
  for(var i=0;i<lines.length;i++){var ln=lines[i];
    var h=ln.match(/^(#{1,6})\s+(.*)$/);
    if(h){closeList();var lv=Math.min(4,h[1].length+1);out.push('<h'+lv+'>'+inline(h[2])+'</h'+lv+'>');continue;}
    if(/^\s*(-{3,}|\*{3,}|_{3,})\s*$/.test(ln)){closeList();out.push('<hr>');continue;}
    var li=ln.match(/^\s*(?:[-*+]|\d+\.)\s+(.*)$/);
    if(li){if(!inList){out.push('<ul>');inList=true;}out.push('<li>'+inline(li[1])+'</li>');continue;}
    if(/^\s*$/.test(ln)){closeList();continue;}
    closeList();out.push('<p>'+inline(ln)+'</p>');
  }
  closeList();return out.join('');
}
// ---- AI Assistant: ChatGPT-style threaded chat (threads stored locally) ----
function getChats(){try{return JSON.parse(localStorage.getItem('nitro-chats')||'[]')}catch{return[]}}
function saveChats(c){try{localStorage.setItem('nitro-chats',JSON.stringify(c.slice(0,50)))}catch{}}
function newChat(){const id='c_'+Date.now();const c=getChats();c.unshift({id,title:'New chat',messages:[],updatedAt:Date.now()});saveChats(c);state.chatId=id;return id;}
function updateChat(id,fn){const c=getChats();const x=c.find(y=>y.id===id);if(x){fn(x);x.updatedAt=Date.now();c.sort((a,b)=>b.updatedAt-a.updatedAt);saveChats(c);}}
function deleteChat(id){const c=getChats().filter(x=>x.id!==id);saveChats(c);if(state.chatId===id)state.chatId=c[0]?c[0].id:null;}
async function sendChat(){
  if(state.chatBusy)return;
  const el=document.getElementById('chat-prompt');const promptText=(el?el.value:'').trim();
  if(!promptText)return;
  if(!getChats().find(x=>x.id===state.chatId)){newChat();}
  updateChat(state.chatId,c=>{c.messages.push({role:'user',text:promptText});if(!c.title||c.title==='New chat')c.title=promptText.slice(0,42);});
  const history=(getChats().find(x=>x.id===state.chatId)?.messages||[]).map(m=>({role:m.role,text:m.text}));
  state.chatBusy=true;render();
  try{
    const r=await api('/api/customer-workspace',{method:'POST',body:JSON.stringify({action:'ask-assistant',prompt:promptText,history})});
    updateChat(state.chatId,c=>{c.messages.push({role:'assistant',text:(r&&r.entry&&r.entry.answer)||'Sorry, I could not answer that. Try again.'});});
  }catch(err){
    updateChat(state.chatId,c=>{c.messages.push({role:'assistant',text:'⚠️ '+((err&&err.message)||'Something went wrong. Please try again.')});});
  }finally{state.chatBusy=false;render();}
}
function assistantPage(){
  const chats=getChats();
  let chat=chats.find(x=>x.id===state.chatId)||chats[0]||null;
  if(chat)state.chatId=chat.id;else state.chatId=null;
  const msgs=chat?chat.messages:[];
  const rail=`<aside class="chat-rail"><button class="btn btn-primary chat-new" id="new-chat">+ New chat</button><div class="chat-list">${chats.length?chats.map(c=>`<div class="chat-item ${c.id===state.chatId?'active':''}" data-chat="${c.id}"><span class="chat-ic">${ICONS.assistant}</span><b>${esc(c.title||'New chat')}</b><span class="chat-del" data-del-chat="${c.id}" title="Delete chat">&times;</span></div>`).join(''):`<p class="chat-empty-list">Your chats will appear here.</p>`}</div></aside>`;
  const thread=msgs.length?msgs.map(m=>m.role==='user'
     ?`<div class="chat-row user"><span class="chat-avatar chat-av-user">${initials(state.session.user)}</span><div class="chat-bubble">${esc(m.text)}</div></div>`
     :`<div class="chat-row ai"><span class="chat-avatar chat-av-bot">${ICONS.assistant}</span><div class="chat-bubble md-body">${mdToHtml(m.text)}</div></div>`).join('')
   :`<div class="chat-blank"><div class="empty-icon">${ICONS.assistant}</div><h3>What are you working on?</h3><p>Ask for a website plan, a campaign idea, a content brief, or have any metric explained.</p></div>`;
  const typing=state.chatBusy?`<div class="chat-row ai"><span class="chat-avatar chat-av-bot">${ICONS.assistant}</span><div class="chat-bubble typing"><i></i><i></i><i></i></div></div>`:'';
  return `<div class="chat-layout"><section class="glass-card panel chat-main"><div class="chat-scroll" id="chat-scroll">${thread}${typing}</div><form id="chat-form" class="chat-input"><textarea class="input" id="chat-prompt" rows="1" placeholder="Ask Nitro anything…"></textarea><button class="btn btn-primary" type="submit" ${state.chatBusy?'disabled':''}>Send</button></form></section>${rail}</div>`;
}

