const PHONE_ICON=_svg('<rect x="6.5" y="2.5" width="11" height="19" rx="2.6"/><path d="M10.3 18.5h3.4"/>');
function msgRow(m){const when=new Date(m.createdAt||Date.now()).toLocaleDateString(undefined,{month:'short',day:'numeric'});return `<div class="msg-row"><span class="msg-chan ${m.channel==='sms'?'is-sms':'is-email'}">${m.channel==='sms'?PHONE_ICON:ICONS.messages}</span><div class="msg-body-col"><b>${esc(m.to)}</b>${m.subject?`<small>${esc(m.subject)}</small>`:''}<p>${esc(String(m.body||'').slice(0,110))}</p></div><div class="msg-meta"><span class="status-pill s-${m.status||'sent'}">${esc(m.status||'sent')}</span><div class="msg-date">${when}</div><button class="row-del" data-del-msg="${m.id}" title="Delete">&times;</button></div></div>`;}
const TWILIO_NUMBERS_URL='https://console.twilio.com/us1/develop/phone-numbers/manage/search';
function connCard(kind,conn){
  const on=!!(conn&&conn.connected);
  const label=kind==='email'?'Email sending':'Texting (SMS)';
  const val=(kind==='email'?conn&&conn.from:conn&&conn.number)||'';
  const sub=on?esc(val||'Connected'):(kind==='email'?'Log every email you send':'Log every text you send');
  const icon=kind==='email'?ICONS.messages:PHONE_ICON;
  const manage=on?`<button class="btn btn-ghost btn-sm" data-connect="${kind}">Edit</button>${kind==='sms'?`<a class="btn btn-ghost btn-sm" href="${TWILIO_NUMBERS_URL}" target="_blank" rel="noopener">Manage number ↗</a>`:''}<button class="btn btn-ghost btn-sm" data-disconnect="${kind}">Disconnect</button>`:`<button class="btn btn-primary btn-sm" data-connect="${kind}">Connect provider</button>`;
  return `<div class="conn-card ${on?'on':''}"><span class="conn-ic">${icon}</span><div class="conn-body"><b>${label}</b><small>${sub}</small></div><span class="conn-status">${on?'<i class="dot dot-on"></i>Connected':'<i class="dot dot-off"></i>Not connected'}</span><div class="conn-actions">${manage}</div></div>`;
}
function messagesPage(){
  const w=workspaceData();const msgs=(w.messages||[]);const conns=w.connections||{email:{},sms:{}};
  const anyOn=(conns.email&&conns.email.connected)||(conns.sms&&conns.sms.connected);
  const tab=state.msgTab;const list=msgs.filter(m=>m.channel===tab);
  const hookUrl=conns.hookToken?`${location.origin}/api/messaging-hook?token=${esc(conns.hookToken)}`:'';
  const connectedNote=anyOn?`<div class="conn-live"><i class="dot dot-on"></i><span>You're connected. Once your provider (like Resend or Twilio) is linked to Nitro, your messages log here automatically. <a href="#assistant">Need a hand? Ask the assistant</a></span></div>`:'';
  const hookBox=anyOn&&hookUrl?`<details class="adv"><summary>Advanced: developer webhook URL</summary><p class="adv-note">Only needed if you're setting up a provider yourself. Paste this into your email/SMS provider's webhook settings.</p><div class="hook-row"><code id="hook-url">${hookUrl}</code><button class="btn btn-sm" data-copy-hook type="button">Copy</button></div></details>`:'';
  const hero=`<section class="glass-card panel auto-card"><span class="auto-tag">Auto-logging</span><h2>Connect once. Every message logs itself.</h2><p>Link your email and texting accounts and Nitro records every message you send — and every reply you get — right here. No logging by hand, no copy-paste. It's the same engine that powers automated outreach on Pro.</p><div class="conn-list">${connCard('email',conns.email)}${connCard('sms',conns.sms)}</div>${connectedNote}${hookBox}<p class="conn-note">Texting runs on your own number (small carrier fees apply). Automated sending &amp; scheduling unlock on <a href="#billing">Pro</a>.</p></section>`;
  const guide=`<section class="glass-card panel guide-card"><div class="panel-head"><h3>How to set it up</h3><span>~5 min</span></div><div class="auto-steps"><div class="auto-step"><span>1</span><div><b>Pick a channel</b><p>Email, texting, or both — whatever you want Nitro to track.</p></div></div><div class="auto-step"><span>2</span><div><b>Get your sender</b><p>Don't have an account yet? These work great with Nitro:</p><p class="prov-line"><b>Email:</b> <a href="https://resend.com" target="_blank" rel="noopener">Resend ↗</a> · <a href="https://sendgrid.com" target="_blank" rel="noopener">SendGrid ↗</a> · <a href="https://postmarkapp.com" target="_blank" rel="noopener">Postmark ↗</a></p><p class="prov-line"><b>Texting:</b> <a href="https://www.twilio.com" target="_blank" rel="noopener">Twilio ↗</a> · <a href="https://telnyx.com" target="_blank" rel="noopener">Telnyx ↗</a> · <a href="https://www.plivo.com" target="_blank" rel="noopener">Plivo ↗</a></p><p class="prov-sub">Verify your domain (email) or grab a number (texting) — small carrier fees apply.</p></div></div><div class="auto-step"><span>3</span><div><b>Connect it here</b><p>Hit <b>Connect</b> above and enter your email address or number. Use <b>Edit</b> anytime to change it.</p></div></div><div class="auto-step"><span>4</span><div><b>Link your provider</b><p>Connect the account from step 2 to Nitro so your sends and replies flow in automatically. Not sure how? Your AI assistant walks you through it — and on Pro, we set it up for you.</p></div></div><div class="auto-step"><span>5</span><div><b>You're live</b><p>Every message logs itself. On <b>Pro</b>, Nitro also writes, sends, and schedules the messages for you.</p></div></div><div class="pro-band"><b>Pro walks you through all of it.</b><p>On a Pro membership, setup is guided end-to-end — we help you verify your domain, connect your number, and switch on automated sending &amp; scheduling. Your AI assistant answers every question along the way, so you're never stuck.</p><div class="pro-actions"><a class="btn btn-primary" href="#billing">Upgrade to Pro</a><a class="btn btn-ghost" href="#assistant">Ask the assistant</a></div></div></section>`;
  const empty=anyOn
    ?`<div class="empty-state" style="padding:34px"><div class="empty-icon">${tab==='sms'?PHONE_ICON:ICONS.messages}</div><h3>Nothing here yet</h3><p>Every ${tab==='sms'?'text':'email'} you send through your connected account will show up here automatically.</p></div>`
    :`<div class="empty-state" style="padding:34px"><div class="empty-icon">${tab==='sms'?PHONE_ICON:ICONS.messages}</div><h3>Connect an account to start</h3><p>Once your ${tab==='sms'?'texting':'email'} account is connected above, your ${tab==='sms'?'texts':'emails'} log here on their own — no manual entry.</p></div>`;
  const log=`<section class="glass-card panel"><div class="panel-head"><h3>Message log</h3><span>${msgs.length} logged</span></div><div class="msg-tabs"><button class="msg-tab ${tab==='email'?'active':''}" data-msg-tab="email">Email</button><button class="msg-tab ${tab==='sms'?'active':''}" data-msg-tab="sms">SMS</button></div><div class="msg-list">${list.length?list.map(msgRow).join(''):empty}</div></section>`;
  return `<div class="messages-page">${hero}<div class="dashboard-grid msg-grid2">${log}${guide}</div></div>`;
}
