function creditStore(u){const owner=(u.email||'').toLowerCase()===OWNER_EMAIL,balance=Number(u.usage?.videoCredits||0);if(owner)return `<section class="glass-card panel credit-store"><div><span class="eyebrow">REEL CREDITS</span><h3>Unlimited owner rendering</h3><p>Your owner account never spends Reel credits.</p></div><span class="video-credit-pill owner-unlimited">Unlimited · Free</span></section>`;const packs=[['starter','5','5','1.00'],['creator','15','12','0.80'],['studio','40','28','0.70']];return `<section class="glass-card panel credit-store"><div class="credit-store-head"><div><span class="eyebrow">REEL CREDIT STORE</span><h3>Buy credits before you render</h3><p>Your balance is <b>${balance} credit${balance===1?'':'s'}</b>. Credits are prepaid, never billed to the owner, and do not expire.</p></div><span class="video-credit-pill">${balance} available</span></div><div class="credit-pack-grid">${packs.map(([id,credits,price,each],index)=>`<article class="credit-pack ${index===1?'recommended':''}"><span>${credits} CREDITS</span><strong>$${price}</strong><small>$${each} per credit</small><p>${credits} × 15-sec Reels<br>or use them on longer videos</p><button class="btn ${index===1?'btn-primary':''}" data-credit-pack="${id}">Buy ${credits} credits</button></article>`).join('')}</div><small class="credit-note">15 sec uses 1 credit · 30 sec uses 2 · 45 sec uses 3 · Secure checkout by Stripe</small></section>`;}
